const tabId = 730410078;
const allProductLinks = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/product/"]'));
  const unique = [];
  const seen = new Set();
  for (const l of links) {
    const title = l.textContent.trim().replace(/\s+/g, ' ');
    if (title && !seen.has(l.href)) {
      seen.add(l.href);
      unique.push({ title, href: l.href });
    }
  }
  return unique;
});
console.log("Total unique product links with text:", allProductLinks.length);
console.log(JSON.stringify(allProductLinks, null, 2));

