const tabId = 730410078;
const searchInfo = await browserjs(tabId, async () => {
  // Let's fetch the search API or search page for "happy birthday"
  const res = await fetch("https://www.bestbuy.com/site/searchpage.jsp?id=pcat17071&st=happy+birthday");
  const html = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const links = Array.from(doc.querySelectorAll('a')).map(a => ({
    text: a.textContent.trim().replace(/\s+/g, ' '),
    href: a.href
  })).filter(a => a.text.toLowerCase().includes('gift card') || a.text.toLowerCase().includes('birthday'));
  return links;
});
console.log("Found links for happy birthday:", JSON.stringify(searchInfo, null, 2));

