const tabId = 730410078;
const apolloData = await browserjs(tabId, () => {
  const data = window[Symbol.for("ApolloSSRDataTransport")];
  if (!data) return "no apollo";
  const jsonStr = JSON.stringify(data);
  const matches = [];
  const re = /"name":"([^"]*)"/g;
  let m;
  while ((m = re.exec(jsonStr)) !== null) {
    if (m[1].toLowerCase().includes('card') || m[1].toLowerCase().includes('birthday') || m[1].toLowerCase().includes('celebrat')) {
      matches.push(m[1]);
    }
  }
  return [...new Set(matches)];
});
console.log("Product names in Apollo cache:", JSON.stringify(apolloData, null, 2));

